import{c as a,Q as i,j as t,m as n}from"./chunks/framework.BPKcPtvA.js";const p=JSON.parse('{"title":"Features","description":"","frontmatter":{"title":"Features","outline":"deep"},"headers":[],"relativePath":"en/features.md","filePath":"en/features.md","lastUpdated":1794895051000}'),o={name:"en/features.md"};function s(r,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>FMCL organizes its functionality into 12 top-level domains. This page lists what each domain actually provides, along with interaction details and limitations; the interface described here follows the current QML version. For installation and building, see the <a href="/en/download">Download page</a>; for step-by-step instructions, see the <a href="/en/guide">Guide</a>.</p><h2 id="versions-and-launch" tabindex="-1">Versions and Launch <a class="header-anchor" href="#versions-and-launch" aria-label="Permalink to &quot;Versions and Launch&quot;">​</a></h2><h3 id="version-detection-and-management" tabindex="-1">Version detection and management <a class="header-anchor" href="#version-detection-and-management" aria-label="Permalink to &quot;Version detection and management&quot;">​</a></h3><ul><li>The installed version list offers search, sorting (name / vanilla version / mod loader) and a total count.</li><li>Each row has details, mods, resources, rename and delete; details show the instance path, required Java and mod count.</li><li>Version metadata is read directly from <code>versions/&lt;instance&gt;/&lt;instance&gt;.json</code> rather than guessed from the folder name.</li><li>The version number is extracted by a multi-level strategy: <code>clientVersion</code> → <code>patches</code> → <code>--fml.mcVersion</code> → <code>inheritsFrom</code> → download and library metadata, including HMCL <code>patches</code> merging and <code>inheritsFrom</code> inheritance chains.</li><li>Mod loader detection covers 9 loaders: Forge, NeoForge, Fabric, Quilt, LegacyFabric, Cleanroom, OptiFine, LiteLoader and LabyMod.</li><li>Renaming an instance updates the folder name, the JSON file name and the internal <code>id</code> together; deletion asks for confirmation first and clears the &quot;recently used version&quot; record.</li><li>File verification hashes files concurrently, and the instance directory can be opened.</li></ul><h3 id="installation-and-mod-loaders" tabindex="-1">Installation and mod loaders <a class="header-anchor" href="#installation-and-mod-loaders" aria-label="Permalink to &quot;Installation and mod loaders&quot;">​</a></h3><ul><li>The installation wizard has its own page: enter a version ID manually, or pick one on the &quot;Release / Snapshot&quot; tabs to fill it in, 20 entries per page with pagination.</li><li>One-click installation for 8 mod loaders: Forge, Fabric, NeoForge, Quilt, LiteLoader, LegacyFabric, Cleanroom and OptiFine; LabyMod is only detected and version-isolated, not installed.</li><li>Vanilla Minecraft installs in parallel with the loader; progress, the current file count, cancellation and retry on failure all live in one progress card.</li><li>Compatibility of the selected loader with the game version is checked before installation and reported directly when it is unsupported.</li><li>China mirror: toggle BMCLAPI in Settings; it covers version manifests, game assets, libraries and loader installers.</li><li>Supports NeoForge&#39;s <code>YY.D.H</code> version naming from 2026 onwards (such as <code>26.1</code>, <code>26.1.1</code>) while staying compatible with the older <code>1.X.Y</code>.</li><li>Version isolation is enabled automatically once a loader is installed, creating <code>mods/</code>, <code>config/</code>, <code>saves/</code>, <code>resourcepacks/</code>, <code>shaderpacks/</code> and similar directories.</li><li>The launch flow includes protocol agreement, announcement confirmation and a resource pre-download check; pre-download supports chunked multithreading, progress display and cancellation.</li></ul><h3 id="launch-and-runtime-diagnostics" tabindex="-1">Launch and runtime diagnostics <a class="header-anchor" href="#launch-and-runtime-diagnostics" aria-label="Permalink to &quot;Launch and runtime diagnostics&quot;">​</a></h3><ul><li>Java runtimes are scanned and version-matched automatically; Settings can switch between automatic, scan results or a custom executable.</li><li>Launch arguments inject G1GC and heap settings; on Java 8, which does not support argument files, it falls back to a plain command line.</li><li>Once the game window is detected the stdout pipe is closed, so a full buffer cannot slow down the final loading stage; the launcher can optionally minimize after launch.</li><li>Abnormal exit detection: a non-zero exit code, or exit code 0 with a crash report or <code>hs_err</code> file written after this launch, opens the crash diagnostics window; older reports are filtered by launch time.</li><li>The diagnostics window shows the exit code and gives entry points to the crash report, game log and JVM crash log; export and analysis still work when a file is missing.</li><li>Local diagnostics recognize 11 common problem classes by keyword (Mixin, missing dependencies, out of memory, mod conflicts and so on) and show at most 3 suggestions.</li><li>ZIP export: crash report, game log, debug log, JVM crash log, launcher log and system information; the temporary file is fully written before it atomically replaces the target.</li><li>Upload the game log to LogShare.CN and copy the share link automatically on success.</li><li>Jingdu AI analysis runs asynchronously; results render as Markdown and can be saved as UTF-8 TXT without BOM.</li></ul><h2 id="resources-and-modpacks" tabindex="-1">Resources and Modpacks <a class="header-anchor" href="#resources-and-modpacks" aria-label="Permalink to &quot;Resources and Modpacks&quot;">​</a></h2><h3 id="my-resources" tabindex="-1">My resources <a class="header-anchor" href="#my-resources" aria-label="Permalink to &quot;My resources&quot;">​</a></h3><ul><li>Four resource types are managed in one place: mods, resource packs, worlds and shader packs; the game version can be switched at the top.</li><li>The version selection order is &quot;route parameter → recently used → first installed&quot;, plus a &quot;Global .minecraft&quot; entry for the shared directory.</li><li>Vanilla instances show only resource packs and worlds; mods and shader packs appear once a mod loader is installed, consistent with the version isolation rules.</li><li>Mod cards read metadata from inside the jar: icon, name, author, modid, version and description.</li><li>Resource packs and shader packs extract preview images such as <code>pack.png</code> from the zip; world zips are extracted to <code>saves/</code> automatically.</li><li>Typed search, pagination, drag-and-drop installation, installation from the file picker, enable and disable (<code>.disabled</code>), delete and open directory.</li><li>Mod update checks query both Modrinth and CurseForge, compare versions and let you select entries for a batch update; downloads run 8 in parallel with hash verification.</li><li>When some updates fail, finished files are kept and the success and failure counts are reported, so nothing is dropped silently.</li></ul><h3 id="online-resources" tabindex="-1">Online resources <a class="header-anchor" href="#online-resources" aria-label="Permalink to &quot;Online resources&quot;">​</a></h3><ul><li>&quot;Browse resources&quot; loads popular content on entry and supports mods, resource packs and shader packs, filtered by keyword, game version and mod loader.</li><li>Dual-source search across Modrinth and CurseForge; without <code>CURSEFORGE_API_KEY</code> it falls back to Modrinth only.</li><li>Filters are prefilled from the source version, and instances with custom names are recognized as well.</li><li>The detail page lets you choose a specific version, preview dependencies and install into a chosen instance; installation resolves <code>required</code> dependencies recursively.</li><li>AI search expands the keyword into several English terms, searches them in parallel, then merges, deduplicates and sorts by download count; it degrades to a normal search when no Jingdu account is signed in.</li><li>Both local and server-side pagination are supported; search results are not cleared when the source is switched.</li></ul><h3 id="modpacks" tabindex="-1">Modpacks <a class="header-anchor" href="#modpacks" aria-label="Permalink to &quot;Modpacks&quot;">​</a></h3><ul><li>The client supports six sources: Modrinth <code>.mrpack</code>, MultiMC/Prism, CurseForge, HMCL, MCBBS and generic archives; the server side accepts <code>.mrpack</code> only.</li><li>Install from a local file, or search and pick a version on the online browse page and download it; the online version list is grouped by Minecraft version and appends 50 entries at a time.</li><li>Metadata, optional components and the component list are parsed; optional files in <code>.mrpack</code> can be selected, while other formats show a read-only list.</li><li>A custom instance name generates that instance&#39;s own version JSON (<code>versions/&lt;instance&gt;/&lt;instance&gt;.json</code>), and the version list, launch flow and version isolation all recognize it.</li><li>Client installation progress spends 90% on the parallel phase and 10% on the loader installation; files download over multiple threads and failures can be retried.</li><li>The version list refreshes automatically when installation finishes; the server list refreshes in sync after a server installation.</li><li>Hosting a server installs the matching vanilla server, accepts the EULA, generates a basic <code>server.properties</code> and detects Forge / Fabric / NeoForge / Quilt server loaders; Fabric API is installed automatically from Modrinth when a Fabric server lacks it.</li><li>Mods whose purpose cannot be determined are collected in a dialog after installation, where each can be disabled or handled individually.</li></ul><h2 id="servers" tabindex="-1">Servers <a class="header-anchor" href="#servers" aria-label="Permalink to &quot;Servers&quot;">​</a></h2><h3 id="list-and-lifecycle" tabindex="-1">List and lifecycle <a class="header-anchor" href="#list-and-lifecycle" aria-label="Permalink to &quot;List and lifecycle&quot;">​</a></h3><ul><li>The installed server list shows name, version, running state and count; each row can be started or stopped directly, and several servers can run at the same time.</li><li>The detail page offers start, stop, join server, open directory and delete (with confirmation).</li><li>Each server has its own maximum memory (1G to 16G), stored in <code>.fmcl_server.json</code> inside that server&#39;s directory and taking precedence over the global setting.</li><li>On a port conflict it moves on to a free port and writes it back to <code>server.properties</code> instead of killing the process holding the port, and both the list and the detail page report it clearly.</li><li><code>nogui</code> is passed explicitly at startup; no server console window appears on Windows; quitting the launcher shuts down every server started by this process.</li><li>The installation page accepts a manually entered version ID or a quick pick from release versions (10 entries per page, paginated, click to fill in).</li><li>Installation progress is shown as &quot;85% client + 15% server jar&quot;; the EULA is accepted automatically, Java is managed and a default configuration is generated.</li></ul><h3 id="console" tabindex="-1">Console <a class="header-anchor" href="#console" aria-label="Permalink to &quot;Console&quot;">​</a></h3><ul><li>Logs are isolated by server route in a reused read-only log view: auto-scroll to the bottom, no line wrapping, the last 5000 lines.</li><li>Shows running state, online players (<code>joined</code> / <code>left</code>, up to 20) and a memory sample every 2 seconds.</li><li>The command input sends on Enter or with the send button; clearing the screen and exporting logs are supported.</li><li>When a server stops unexpectedly, a dialog on any page asks you to confirm the exit; choosing to analyze reuses the crash service for AI diagnostics.</li></ul><h3 id="configuration-editor" tabindex="-1">Configuration editor <a class="header-anchor" href="#configuration-editor" aria-label="Permalink to &quot;Configuration editor&quot;">​</a></h3><ul><li>49 <code>server.properties</code> entries are shown in 7 categories, plus memory, EULA and directory, for 52 items in total.</li><li>Cross-category search (name, key, description), six control types (BOOL / INT / STR / ENUM / memory / read-only), badges for advanced entries and range hints.</li><li>Entries or the current category can be restored to defaults; an out-of-range INT value opens a dialog and highlights the field in red.</li><li>Raw text editing: line endings are normalized and written back after confirmation.</li><li>Saving only updates the keys that changed and keeps comments and unknown keys; the page guards against leaving with unsaved changes.</li><li>After saving, per-server memory and the detail page dropdown stay in sync; changes to a running server take effect after a restart.</li></ul><h3 id="server-mods-and-resource-packs" tabindex="-1">Server mods and resource packs <a class="header-anchor" href="#server-mods-and-resource-packs" aria-label="Permalink to &quot;Server mods and resource packs&quot;">​</a></h3><ul><li>Manages <code>mods/</code> and <code>resourcepacks/</code> in the server directory: search, pagination, drag-and-drop and file-picker installation, enable and disable, delete.</li><li>The mod list can be exported, updates checked and applied in a batch, and client-only mods filtered out.</li><li>Online browsing of server mods uses Modrinth only, with AI search, backend pagination and installation into the current server.</li></ul><h2 id="terracotta-multiplayer" tabindex="-1">Terracotta Multiplayer <a class="header-anchor" href="#terracotta-multiplayer" aria-label="Permalink to &quot;Terracotta Multiplayer&quot;">​</a></h2><ul><li>Windows only; built on EasyTier virtual networking, with P2P traversal across many NAT types.</li><li>Environment detection and one-click EasyTier installation: several mirrors are speed-tested in parallel with automatic fallback.</li><li>Terracotta codes use a <code>U/</code> prefixed 21-character Base34 encoding that includes a checksum, and remain compatible with legacy <code>XXXXX-XXXXX-XXXXX-XXXXX-XXXXX</code> codes.</li><li>Create a lobby: enter the Minecraft port and a display name, a code is generated and EasyTier starts as the host; the host is ready in about 5 seconds.</li><li>Join a lobby: enter the code to connect; guests connect in about 3 seconds and look for the host at most twice; the code can be copied.</li><li>The member list puts the host first and shows online state and guest-to-host latency; members time out after 10 seconds, and a failed heartbeat marks the host offline automatically.</li><li>TCP port forwarding (up to 10 concurrent) and LAN broadcast emulation; after joining, broadcast packets are sent to <code>127.0.0.1:4445</code>.</li><li>LAN world scanning (3.5 seconds) only lists results and never joins automatically; it listens on both IPv4 and IPv6 multicast.</li><li>The EasyTier log keeps up to 5000 lines and survives page switches; leaving a lobby and abnormal exits are both cleaned up.</li><li>Like every domain unavailable on non-Windows systems, non-Windows shows an explicit unsupported notice.</li></ul><h2 id="world-save-backups" tabindex="-1">World Save Backups <a class="header-anchor" href="#world-save-backups" aria-label="Permalink to &quot;World Save Backups&quot;">​</a></h2><ul><li>The global <code>saves/</code> directory and every isolated version directory are scanned automatically and rescanned on refresh.</li><li>The backup table shows time (local time zone), size, game version and note; restore, verify, export ZIP and delete are supported, and restore and delete ask for confirmation.</li><li>Manual backups take a note and show real compression progress; compression level 1 / 3 / 6 / 9.</li><li>Automatic backups can be configured separately for &quot;before the game starts&quot; and &quot;after the game exits&quot;; toggles are written to the configuration immediately.</li><li>Backup settings: storage path, keep 5 / 10 / 20 / 30 / 50 / unlimited per world save, and how to handle the old save on restore (rename / overwrite / recycle bin).</li><li>ZIP integrity is verified before a restore; free disk space is checked before a backup; the oldest backups are deleted automatically once the retention count is exceeded.</li><li>The index records metadata in <code>index.json</code> and stays compatible with older index versions.</li></ul><h2 id="music" tabindex="-1">Music <a class="header-anchor" href="#music" aria-label="Permalink to &quot;Music&quot;">​</a></h2><h3 id="playback-and-queue" tabindex="-1">Playback and queue <a class="header-anchor" href="#playback-and-queue" aria-label="Permalink to &quot;Playback and queue&quot;">​</a></h3><ul><li>Playback uses <code>QMediaPlayer</code> streaming and never downloads a whole track first; progress, volume, mute, fade in and out and playback state restoration are supported.</li><li>A single playback queue with four modes: sequential, list repeat, single repeat and shuffle.</li><li>Queue entries can be jumped to, moved up, moved down and removed; every track list shares the same row component.</li><li>Playback history is recorded automatically, a repeated track moves to the front, up to 200 entries.</li><li>The main window has a music control bar at the bottom; on Windows it integrates SMTC (metadata, state, progress, media keys).</li><li>Volume leveling is on by default: tracks are analyzed against a -14 LUFS target and normalized, so the volume does not jump between tracks; results are cached and the next track is prefetched.</li></ul><h3 id="discovery-local-and-online" tabindex="-1">Discovery, local and online <a class="header-anchor" href="#discovery-local-and-online" aria-label="Permalink to &quot;Discovery, local and online&quot;">​</a></h3><ul><li>Discover home: daily recommendations, recommended playlists, charts and new music.</li><li>Local music: a recursive scan of MP3 / FLAC / OGG / WAV / M4A / AAC, reading tags, embedded cover art and duration, with &quot;play all&quot;.</li><li>Online search covers five main sources - NetEase Cloud Music, QQ Music, Kuwo, Kugou and Migu - with Bilibili as a cross-source fallback.</li><li>The highest available quality is chosen automatically; search terms come with suggestions, results return source by source, and pages are guarded by a request sequence number.</li><li>When playback fails or a link is invalid, the same track is searched across sources, and a duration check of ±15 seconds filters out covers and instrumentals.</li><li>When Bilibili returns a <code>v_voucher</code> risk check, a verification window opens the system browser; once the slider is solved the <code>grisk_id</code> is obtained automatically and the request is retried.</li><li>Original-track detection clusters by normalized title and <code>originSongSimpleData</code>, combined with release date, a curated ID table, a same-title-different-song table and an encyclopedia fallback; tracks that cannot be decided are left unmarked.</li></ul><h3 id="playlists-lyrics-and-desktop-lyrics" tabindex="-1">Playlists, lyrics and desktop lyrics <a class="header-anchor" href="#playlists-lyrics-and-desktop-lyrics" aria-label="Permalink to &quot;Playlists, lyrics and desktop lyrics&quot;">​</a></h3><ul><li>The playlist sidebar contains all songs, liked music, recently played, user playlists and NetEase Cloud playlists.</li><li>Playlists can be created, renamed and deleted; system playlists cannot be edited; sorting supports added time and title (Chinese sorted by pinyin initial).</li><li>Playlists are written atomically to <code>data/music/</code> with a 30-second fallback; the old <code>data/music.json</code> is migrated read-only.</li><li>NetEase Cloud accounts support QR sign-in and show the VIP tier and credential expiry; remote playlists sync read-only and refresh every 10 minutes.</li><li>Lyrics support LRC, translations and romanization; the full-screen playback page has an event overlay.</li><li>Desktop lyrics scroll in three lines with the current line highlighted; they can be turned on, locked, or unlocked and dragged, and opacity and position are persisted.</li><li>Global hotkeys: <code>Ctrl+Shift+Space</code> play/pause, <code>Ctrl+Shift+Left/Right</code> previous/next, <code>Ctrl+Shift+Down</code> stop, <code>Ctrl+Shift+Up/PageDown</code> volume, <code>Ctrl+Shift+Alt+M</code> mute.</li><li>Audio effects (EQ / reverb / pitch shift / speed) and a player mini mode are not provided.</li></ul><h2 id="toolbox" tabindex="-1">Toolbox <a class="header-anchor" href="#toolbox" aria-label="Permalink to &quot;Toolbox&quot;">​</a></h2><h3 id="nine-entries" tabindex="-1">Nine entries <a class="header-anchor" href="#nine-entries" aria-label="Permalink to &quot;Nine entries&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td>Game junk cleanup</td><td>Grouped checkboxes by directory, scans <code>.log</code> / <code>.tmp</code>, adjustable scan depth, skips system directories, deletes after confirmation</td></tr><tr><td>Port check</td><td>TCP connectivity, latency and error details; built-in MC Java, Bedrock, HTTP and HTTPS presets plus Server List Ping (MOTD, version, player count, player sample, favicon)</td></tr><tr><td>Hash calculation</td><td>MD5 / SHA1 / SHA256 / SHA512, read in chunks in the background, result can be copied</td></tr><tr><td>Coordinate conversion</td><td>Overworld and Nether X/Z conversion, Y unchanged</td></tr><tr><td>Today&#39;s luck</td><td>A 0-100 score and grade generated from a date seed, with the last 60 days of history persisted</td></tr><tr><td>Fun facts</td><td>40 built-in Minecraft facts, one per day, switchable at random</td></tr><tr><td>Knowledge quiz</td><td>AI-generated questions, the question bank is persisted and refilled automatically when fewer than 5 remain</td></tr><tr><td>Multithreaded download</td><td>Custom URL, User-Agent and save path, with pause, cleanup on cancel and cross-process resume</td></tr><tr><td>Related sites</td><td>29 official, community, resource and tool sites, with names, descriptions and tags in four languages</td></tr></tbody></table><h3 id="performance-monitor" tabindex="-1">Performance monitor <a class="header-anchor" href="#performance-monitor" aria-label="Permalink to &quot;Performance monitor&quot;">​</a></h3><ul><li>Two entry points: the monitor button in the top bar and the global hotkey <code>Ctrl+Shift+M</code>.</li><li>A borderless, always-on-top, semi-transparent floating window that can be dragged; top-right by default with a persisted position.</li><li>Shows CPU usage and frequency, memory usage and swap, GPU name, utilization, video memory and temperature.</li><li>GPU data is probed across NVIDIA / AMD vendors (pynvml, nvidia-smi, rocm-smi, amd-smi, gpu-detector); a placeholder is shown when no data is available.</li><li>A 10-second hotkey hint appears when the window opens; values refresh every second and GPU data every 2 seconds.</li></ul><h2 id="achievements-and-notifications" tabindex="-1">Achievements and Notifications <a class="header-anchor" href="#achievements-and-notifications" aria-label="Permalink to &quot;Achievements and Notifications&quot;">​</a></h2><ul><li>47 achievements in 9 categories: gamers, modders, server owners, backup habit, multiplayer, AGENT, personalization, power users and music life.</li><li>Some achievements have I / II / III stages that upgrade automatically by count or progress; cards show current progress, stage and unlocked badge.</li><li>Triggers cover launching the game, installing a version, backups, servers, music playback, mode switching and more, with a notification in the bottom-right corner on unlock.</li><li>Data lives in <code>achievements.db</code> (SQLite WAL) and is protected from concurrent access by a reentrant lock.</li><li>The daily check-in records consecutive days opened and counts towards the &quot;check-in master&quot; achievement.</li><li>Cloud save sync: downloaded and merged entry by entry at startup (keeping the higher stage or progress) and pushed automatically after an unlock; manual sync, cloud reset and local reset are supported.</li><li>Global notifications share one toast stack with four levels: info / success / warning / error.</li></ul><h2 id="agent-and-voice" tabindex="-1">AGENT and Voice <a class="header-anchor" href="#agent-and-voice" aria-label="Permalink to &quot;AGENT and Voice&quot;">​</a></h2><h3 id="conversations-and-tools" tabindex="-1">Conversations and tools <a class="header-anchor" href="#conversations-and-tools" aria-label="Permalink to &quot;Conversations and tools&quot;">​</a></h3><ul><li>Three-column layout: session list, message stream and todo panel; sessions can be created, switched, renamed and deleted, and history is saved automatically.</li><li>Markdown renders headings, paragraphs, lists, tables and fenced code blocks without WebEngine; thinking blocks can be collapsed.</li><li>Tool call cards show arguments and results and can be expanded and copied; output streams over SSE, with stop, regenerate and copy.</li><li>High-risk commands, file modifications and <code>ask_user</code> all require confirmation; file writes, edits and deletes preview a diff first.</li><li>33 tools in total cover versions, mods, resource packs, shader packs, modpacks, servers, system commands, web search, web fetching, file read and write, search and listing, session tasks and user interaction; the tool loop is capped at 50 rounds.</li><li>Web search prefers Bing and falls back to DuckDuckGo; web fetching can output Markdown, plain text or HTML.</li><li>Four provider types are supported: Jingdu, OpenAI, Anthropic and custom OpenAI-compatible endpoints; the thinking toggle and its intensity are adjustable.</li><li>All 33 tools have three permission levels - allow / ask / deny - and the rules are persisted.</li><li>Skills can be listed, created, opened and edited, and their content is injected into the system context; the skill directory is <code>data/agent/skills/{name}/SKILL.md</code>.</li><li>The quick input in the top bar sends on Enter and jumps to AGENT; closing the window while a request is processing requires confirmation.</li><li>The CLI still works: <code>python main.py --agent &quot;...&quot;</code> or <code>python main.py -A</code>.</li></ul><h3 id="voice-input" tabindex="-1">Voice input <a class="header-anchor" href="#voice-input" aria-label="Permalink to &quot;Voice input&quot;">​</a></h3><ul><li>Both the AGENT input and the top input of the main window can record with one click, and the recognized text is filled in automatically.</li><li>Based on the offline SenseVoice-Small model with built-in punctuation and number conversion, adapting between DirectML and CPU.</li><li>The model downloads automatically on first use; when GitHub is slow, a local model ZIP can be imported in Settings.</li><li>The voice button stays disabled until the model is ready, so a click always gets feedback.</li></ul><h2 id="bedrock-edition" tabindex="-1">Bedrock Edition <a class="header-anchor" href="#bedrock-edition" aria-label="Permalink to &quot;Bedrock Edition&quot;">​</a></h2><ul><li>Windows 10 19041 or later only; two builds, UWP (AppX registration) and GDK (raw launch after XVD extraction).</li><li>Installed cards show name, version, UWP/GDK build and Release/Preview/Test channel, and support launch, delete, details and opening the version directory.</li><li>The version catalog comes from McAppx with multi-source fallback; search, All/UWP/GDK filtering, 20 entries per page and pagination.</li><li>The MCAPPX terms must be accepted before installation; GDK checks for the .NET 10 SDK and points to the official download, and authentication components are downloaded on demand after explicit consent.</li><li>Microsoft device code sign-in: show the code, copy it, open the link and poll for the result.</li><li>Installation uses real download progress, multithreaded resume and MD5 verification.</li><li>GDK XVD extraction is delegated to a .NET helper (BedrockLauncher.Core) that prefers AES-NI and falls back to software decryption on older CPUs.</li><li>Environment detection and repair: developer mode, Gaming Services, the VC++ runtime and GameInput; when Gaming Services is missing it is installed with winget before the download.</li><li>Launch prefers the version selected by the user and falls back to the installed Xbox version on failure.</li></ul><h2 id="settings-and-personalization" tabindex="-1">Settings and Personalization <a class="header-anchor" href="#settings-and-personalization" aria-label="Permalink to &quot;Settings and Personalization&quot;">​</a></h2><h3 id="settings-sections" tabindex="-1">Settings sections <a class="header-anchor" href="#settings-sections" aria-label="Permalink to &quot;Settings sections&quot;">​</a></h3><ul><li>9 sections: launcher, Java, theme, music account, logs, about, accounts, AI and plugins.</li><li>Settings use a whole-domain draft: edits go only into the draft and can preview themes and languages; saving writes to disk, cancelling restores the previous values, and leaving with unsaved changes prompts.</li><li>Launcher section: minimize after launch, China mirror toggle, download thread count (1-255), interface language.</li><li>Java section: automatic / scan / custom modes, custom path browsing, applying a scan result by radio selection and refreshing.</li><li>Theme section: 5 presets, importing a <code>.json</code> theme, a custom Hex accent color, random color and the version-based dynamic theme.</li><li>Languages are Simplified Chinese, English, Traditional Chinese and Japanese, and switch immediately without a restart.</li></ul><h3 id="accounts-and-skins" tabindex="-1">Accounts and skins <a class="header-anchor" href="#accounts-and-skins" aria-label="Permalink to &quot;Accounts and skins&quot;">​</a></h3><ul><li>Microsoft sign-in: PKCE OAuth, with device code sign-in as a fallback.</li><li>Offline sign-in: a UUID is generated locally, no network verification needed.</li><li>Yggdrasil external sign-in: supports third-party authentication servers such as skin sites and injects <code>authlib-injector</code> automatically.</li><li>Microsoft tokens are checked before launch and renewed with <code>refresh_token</code>; accounts are stored in <code>accounts.json</code> and tokens are encrypted.</li><li>Accounts can be added, deleted, switched and set as current; encrypted <code>.fmcl_accounts</code> files can be imported and exported.</li><li>Skins support 64x64 / 64x32 / 128x128 / 128x64 PNG and are copied to <code>.minecraft/skins/</code> automatically.</li></ul><h3 id="jingdu-account" tabindex="-1">Jingdu account <a class="header-anchor" href="#jingdu-account" aria-label="Permalink to &quot;Jingdu account&quot;">​</a></h3><ul><li>Settings → Jingdu account: sign in with a username and password, and errors are classified as wrong credentials, HTTP, network or missing token.</li><li>After signing in it shows the username, UUID, level, signature and AI credits, and can be refreshed or signed out.</li><li>Both the token and the username are stored with Fernet encryption; user information is cached in memory only.</li><li>An HTTP 401 reports an expired session and clears the local token.</li></ul><h3 id="themes-and-interface" tabindex="-1">Themes and interface <a class="header-anchor" href="#themes-and-interface" aria-label="Permalink to &quot;Themes and interface&quot;">​</a></h3><ul><li>The default theme plus Ocean Blue, Forest Green, Lavender Purple and Sunset Orange presets, switchable in one click.</li><li>A custom accent color supports <code>#RRGGBB</code> validation, clearing an empty value and random generation.</li><li>The version-based dynamic theme adjusts the accent color to the current Minecraft version (versions such as 1.13 through 1.21 each have their own palette).</li><li>The interface uses QML-drawn components and the FluentUI module; colors come only from theme variables, with a consistent icon set and 110 ms transitions. No gradients are used and no emoji appear in the interface.</li><li>The 12 top-level domains are grouped as &quot;Game / Resources and Multiplayer / Tools and Extensions&quot;; domains unavailable on the current platform do not appear in the navigation.</li></ul><h2 id="plugins-updates-and-system-integration" tabindex="-1">Plugins, Updates and System Integration <a class="header-anchor" href="#plugins-updates-and-system-integration" aria-label="Permalink to &quot;Plugins, Updates and System Integration&quot;">​</a></h2><h3 id="plugin-system" tabindex="-1">Plugin system <a class="header-anchor" href="#plugin-system" aria-label="Permalink to &quot;Plugin system&quot;">​</a></h3><ul><li>Plugins ship as <code>.fmpl</code> archives containing <code>plugin.json</code> and Python modules; local installation and an online marketplace are supported.</li><li>The plugin manager can browse, enable, disable, uninstall and inspect permissions; enabling, disabling and installing hot-reload without a restart.</li><li>Permissions have three levels, low, medium and high: low risk is confirmed once, medium risk can be revoked, high risk prompts every time.</li><li>20+ hook points cover the application, game, versions, servers, downloads and the UI lifecycle.</li><li>An exception in one plugin is isolated and does not affect other plugins or the launcher; version constraints, circular dependency detection and topological sorting are applied across plugins.</li><li>A failed update rolls back to the previous version automatically; each plugin has its own <code>data/</code> and <code>configs/</code> directories.</li><li>UI API v2: plugins can provide pages in QML, fetch data through <code>Plugins.call</code> and register into the top-level navigation; pages of plugins that declare <code>ui_api: 1</code> are not loaded, while non-UI hooks are unaffected.</li><li>See <a href="/en/plugin">Plugin development</a> for details.</li></ul><h3 id="automatic-updates" tabindex="-1">Automatic updates <a class="header-anchor" href="#automatic-updates" aria-label="Permalink to &quot;Automatic updates&quot;">​</a></h3><ul><li>Automatic updates are currently Windows only: a GitHub Release check runs at startup (it can be disabled), and a new version shows its version number and changelog.</li><li>Settings → About can check manually, download and launch the NSIS installer; once the installer starts, the normal shutdown chain is used.</li><li>Linux and macOS have no automatic installation; update through a tarball, a setup script or the source.</li></ul><h3 id="status-and-system-integration" tabindex="-1">Status and system integration <a class="header-anchor" href="#status-and-system-integration" aria-label="Permalink to &quot;Status and system integration&quot;">​</a></h3><ul><li>The bottom status bar shows operation results; success, failure and warning states clear after 10 seconds, while loading states persist.</li><li>The toast stack is for asynchronous results that do not belong in the status bar; the same event is queued only once to avoid duplicates.</li><li>Windows supports SMTC and global hotkeys; on Linux, global hotkeys may be unavailable in non-root environments.</li></ul><h2 id="security-and-data" tabindex="-1">Security and Data <a class="header-anchor" href="#security-and-data" aria-label="Permalink to &quot;Security and Data&quot;">​</a></h2><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li>All HTTP requests verify SSL certificates by default.</li><li>Tokens are stored with a random key file and Fernet symmetric encryption; <code>.fmcl_key</code> can be migrated together with <code>config.json</code>.</li><li>User input passes whitelist and path validation to prevent command injection and path traversal.</li><li>Mod downloads verify SHA1 / SHA512 and update packages verify SHA256; the downloader supports connection pooling, exponential backoff retries and Range resume.</li><li>Configuration and backup indexes use atomic writes with a temporary file and a rename; a failed modpack installation cleans up partial files and directories.</li></ul><h3 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h3><ul><li>JSON prefers orjson and falls back to the standard library when it is missing.</li><li>File verification hashes concurrently on a thread pool, and downloads process batches concurrently with asyncio + aiohttp.</li><li>JVM arguments inject G1GC and a fixed heap; the stdout pipe is closed once the game window appears.</li><li>Modules outside the first screen are imported lazily; mirror URL conversions are cached; version lookup uses a set for O(1).</li></ul><h3 id="data-and-logs" tabindex="-1">Data and logs <a class="header-anchor" href="#data-and-logs" aria-label="Permalink to &quot;Data and logs&quot;">​</a></h3><ul><li>The data directory prefers the program directory (portable mode) and falls back to the user data directory when it is not writable.</li><li>Configuration is saved as <code>config.json</code>, the launcher log is <code>latest.log</code>, and structured logs are appended to <code>latest_structured.log</code> as JSONL.</li><li>Uninstalling removes only program files and shortcuts, keeping user data such as <code>config.json</code>, <code>.minecraft</code>, accounts, playlists and achievements.</li></ul><h2 id="platform-support-and-limitations" tabindex="-1">Platform Support and Limitations <a class="header-anchor" href="#platform-support-and-limitations" aria-label="Permalink to &quot;Platform Support and Limitations&quot;">​</a></h2><ul><li><strong>Windows</strong>: the QML build ships an x64 installer only (PySide6 6.7.3 has no win32 wheels). On 32-bit systems keep using the 2.12.6 installer; the data directory is the same as in the new version.</li><li><strong>Linux</strong>: source builds and a tarball for x86_64; the setup script registers the <code>fmcl</code> command. Global hotkeys may be unavailable in non-root environments.</li><li><strong>macOS</strong>: running from source only, no <code>.dmg</code> at the moment.</li><li>Bedrock Edition and Terracotta multiplayer are Windows only; on non-Windows an explicit unsupported notice is shown instead of a blank page.</li><li>Music does not provide audio effects or a mini mode.</li><li>Only the QML interface is offered; plugin pages use the QML extension protocol and the command-line mode remains in <code>main.py</code>.</li></ul>',75)])])}const m=a(o,[["render",s]]);export{p as __pageData,m as default};
